let dotNetRef = null;
let timeoutId = null;
let isIdle = false;

const activityEvents = ["mousemove", "keydown", "click", "scroll"];

function onActivity() {
    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync("OnActiveCallback");
    }
    resetTimer();
}

function resetTimer() {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnIdleCallback");
    }, timeoutSeconds * 1000);
}

let timeoutSeconds = 300;

export function initialize(ref, seconds) {
    dotNetRef = ref;
    timeoutSeconds = seconds;
    isIdle = false;

    for (const event of activityEvents) {
        document.addEventListener(event, onActivity, { passive: true });
    }

    resetTimer();
}

export function dispose() {
    clearTimeout(timeoutId);
    timeoutId = null;

    for (const event of activityEvents) {
        document.removeEventListener(event, onActivity);
    }

    dotNetRef = null;
    isIdle = false;
}

